mod program_module_foreign_process_runtime_root_support;
mod support;

use std::ffi::{OsStr, OsString};
use std::fs;
use std::path::Path;

use program_module_foreign_process_runtime_root_support::{
    create_python_interpreter_root, create_python_wheel_root,
};
use serde_json::Value as JsonValue;
use support::{run, run_json};

const PYTHON_ROOT: &str = r"C:\Python314";

#[test]
fn verified_wheel_record_runs_offline_matches_explicit_tree_and_rejects_tampering() {
    let python = Path::new(PYTHON_ROOT);
    let work = tempfile::tempdir().unwrap();
    let runtime_root = create_python_interpreter_root(work.path(), python);
    let wheel_root = create_python_wheel_root(work.path());
    let script = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/python_dependency_text_transform.py");

    let imported = provision(
        work.path(),
        python,
        &script,
        &runtime_root,
        &wheel_root,
        true,
    );
    let explicit = provision(
        work.path(),
        python,
        &script,
        &runtime_root,
        &wheel_root,
        false,
    );
    for field in [
        "module_cid",
        "capsule_root_cid",
        "closure_cid",
        "runtime_cid",
        "runtime_support_cid",
    ] {
        assert_eq!(imported[field], explicit[field]);
    }
    assert_eq!(
        imported["closure_schema"],
        "unicodex.foreign_process.closure.v18"
    );
    assert_eq!(
        imported["runtime_schema"],
        "unicodex.foreign_process.runtime.v18"
    );
    let module = text(&imported, "module_cid");
    assert_eq!(
        invoke(work.path(), module, "record")["result"],
        "wheel:DROCER"
    );

    let bundle = work.path().join("python-wheel.bundle");
    assert!(run_json(
        work.path(),
        [
            OsString::from("object"),
            OsString::from("bundle"),
            OsString::from("export"),
            OsString::from(module),
            OsString::from("--out"),
            bundle.as_os_str().to_owned(),
            OsString::from("--format"),
            OsString::from("json"),
        ],
    )["ok"]
        .as_bool()
        .unwrap());
    let clean = tempfile::tempdir().unwrap();
    assert!(run_json(
        clean.path(),
        [
            OsStr::new("object"),
            OsStr::new("bundle"),
            OsStr::new("import"),
            bundle.as_os_str(),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    )["ok"]
        .as_bool()
        .unwrap());
    materialize(clean.path(), module);
    assert_eq!(
        invoke(clean.path(), module, "offline")["result"],
        "wheel:ENILFFO"
    );

    fs::write(
        wheel_root.join("capsule_dependency/transform.py"),
        "def transform(value):\n    return 'tampered:' + value\n",
    )
    .unwrap();
    let rejected = provision_output(
        work.path(),
        python,
        &script,
        &runtime_root,
        &wheel_root,
        true,
    );
    assert!(!rejected.status.success());
    assert!(String::from_utf8_lossy(&rejected.stderr).contains("RECORD hash mismatch"));
}

