fn assert_rejected(cwd: &Path, vessel: &str, message: &str) {
    let output = run(cwd, command("verify", vessel));
    assert_eq!(output.status.code(), Some(2));
    let json: JsonValue = serde_json::from_slice(&output.stdout).unwrap();
