fn command<'a>(operation: &'a str, value: &'a str) -> [&'a OsStr; 7] {
    [
        OsStr::new("project"),
        OsStr::new("authority"),
        OsStr::new("vessel"),
        OsStr::new(operation),
        OsStr::new(value),
        OsStr::new("--format"),
        OsStr::new("json"),
    ]
}

fn load(store: &ObjectStore, cid: &str) -> Value {
    let Node::Value(value) = decode_node(&store.get_canonical(cid).unwrap()).unwrap() else {
        panic!("authority vessel must be a value")
    };
    value
}

fn mutate<F>(store: &ObjectStore, value: &Value, mutate: F) -> String
where
    F: FnOnce(&mut Vec<(Value, Value)>),
{
    let Value::Map(mut entries) = value.clone() else {
        unreachable!()
    };
    mutate(&mut entries);
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}

fn field_mut<'a>(entries: &'a mut [(Value, Value)], field: &str) -> &'a mut Value {
    &mut entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(field.to_owned()))
        .unwrap()
        .1
}

